DROP TABLE IF EXISTS `maintenancebreakdown`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `maintenancebreakdown` (
  `id` int NOT NULL AUTO_INCREMENT,
  `month` varchar(20) NOT NULL,
  `year` varchar(10) NOT NULL,
  `keBillamount` int NOT NULL DEFAULT '0',
  `kwsbBillamount` int NOT NULL DEFAULT '0',
  `repair` int NOT NULL DEFAULT '0',
  `guardSalary` int NOT NULL DEFAULT '0',
  `sweeperSalary` int NOT NULL DEFAULT '0',
  `misc` int NOT NULL DEFAULT '0',
  `remainingAmount` varchar(20) NOT NULL,
  `collectedAmount` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

